#!/usr/bin/env node
// Bundles the admin client (src/admin/client.ts) into a string module that the
// page shell injects. Runs before tsc so page.tsx can import the generated file.
import { build } from 'esbuild';
import { writeFileSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

const root = join(dirname(fileURLToPath(import.meta.url)), '..');

const result = await build({
	entryPoints: [join(root, 'src/admin/client.ts')],
	bundle: true,
	minify: true,
	format: 'iife',
	target: 'es2022',
	platform: 'browser',
	write: false,
});

const code = result.outputFiles[0].text;
const out = `// Generated by scripts/build-admin-client.mjs. Do not edit.\nexport const ADMIN_CLIENT = ${JSON.stringify(code)};\n`;
writeFileSync(join(root, 'src/admin/client-bundle.generated.ts'), out);
console.log(`Bundled admin client (${code.length} bytes).`);
